export function DashboardMiniPreview({ kind, model = "pro", theme = "dark" }: { kind: DashboardKind; model?: DashboardModel; theme?: DashboardTheme }) {
  const bars = kind === "finance" ? [42, 61, 48, 76, 68, 88] : kind === "marketing" ? [28, 45, 72, 54, 84, 70] : [35, 52, 47, 69, 75, 91];
  const ana = kind === "anacraft";
  const accent = ana ? "bg-pink-400" : "bg-sky-400";

  if (model === "simple") { const dark = theme === "dark"; const minimal = minimalPalettes[theme]; return <div className={cn("dashboard-preview relative h-36 overflow-hidden rounded-xl border p-4", dark ? "border-white/[.1]" : "border-slate-200")} style={{ backgroundColor: minimal.background }}>
    <div className="flex h-full gap-4"><div className={cn("flex w-[38%] flex-col justify-between border-r pr-4", dark ? "border-white/[.1]" : "border-slate-200")}><span className={cn("h-1.5 w-12 rounded-full", dark ? "bg-slate-600" : "bg-slate-300")} /><div><span className={cn("block h-5 w-16 rounded", dark ? "bg-white/80" : "bg-slate-800")} /><span className={cn("mt-2 block h-1.5 w-10 rounded-full", dark ? "bg-slate-600" : "bg-slate-300")} /></div><span className="h-1.5 w-14 rounded-full" style={{ backgroundColor: minimal.primary }} /></div><div className="flex min-w-0 flex-1 flex-col justify-between"><div className="flex items-center justify-between"><span className={cn("h-1.5 w-12 rounded-full", dark ? "bg-slate-600" : "bg-slate-300")} /><span className="size-2 rounded-full" style={{ backgroundColor: minimal.primary }} /></div><div className="relative h-16"><svg viewBox="0 0 120 48" className="h-full w-full" aria-hidden="true"><path d="M2 39 C20 37, 25 22, 42 27 S67 34, 78 18 S100 8, 118 13" fill="none" stroke={minimal.primary} strokeWidth="2.5" strokeLinecap="round" /><path d="M2 39 C20 37, 25 22, 42 27 S67 34, 78 18 S100 8, 118 13 L118 48 L2 48 Z" fill={`${minimal.primary}18`} /></svg></div><div className="flex gap-2"><span className={cn("h-5 flex-1 rounded border", dark ? "border-white/[.1] bg-white/[.06]" : "border-slate-200 bg-white")} /><span className={cn("h-5 flex-1 rounded border", dark ? "border-white/[.1] bg-white/[.06]" : "border-slate-200 bg-white")} /></div></div></div>
  </div>;
  }

  if (model === "turbo") return <div className="dashboard-preview relative h-36 overflow-hidden rounded-xl border border-blue-400/25 bg-[#06172e] p-2.5"><div className="mb-2 grid grid-cols-4 gap-1.5">{[0, 1, 2, 3].map((item) => <span key={item} className="h-7 rounded border border-blue-300/15 bg-blue-300/[.055] p-1.5"><i className={cn("block h-1 w-3 rounded-full", item % 2 ? "bg-cyan-300/70" : "bg-blue-400/80")} /><i className="mt-1 block h-1.5 w-5 rounded-sm bg-white/65" /></span>)}</div><div className="grid h-[84px] grid-cols-[1fr_3fr] gap-2"><div className="flex flex-col gap-1.5 rounded border border-blue-300/15 bg-black/15 p-2">{[70, 92, 56, 78].map((width, index) => <span key={index} className="h-1.5 rounded-full bg-blue-300/20"><i className="block h-full rounded-full bg-cyan-300/70" style={{ width: `${width}%` }} /></span>)}</div><div className="flex items-end gap-1.5 rounded border border-blue-300/15 bg-blue-300/[.025] px-2 pb-2 pt-3">{bars.map((height, index) => <span key={index} className="flex-1 rounded-sm bg-gradient-to-t from-blue-700 to-cyan-300" style={{ height: `${height}%` }} />)}</div></div></div>;

  if (model === "premium") return <div className="dashboard-preview model-preview-premium relative h-36 overflow-hidden rounded-xl border border-cyan-300/25 bg-[#031017] p-2.5"><div className="grid h-full grid-cols-[1.25fr_.75fr] gap-2"><div className="grid grid-rows-[.7fr_1.3fr] gap-2"><div className="grid grid-cols-2 gap-2"><span className="border border-cyan-300/20 bg-black/25 p-2"><i className="block h-1 w-7 bg-cyan-300/60" /><i className="mt-2 block h-2 w-10 bg-white/70" /></span><span className="border border-emerald-300/20 bg-black/25 p-2"><i className="block h-1 w-5 bg-emerald-300/60" /><i className="mt-2 block h-2 w-8 bg-white/70" /></span></div><div className="flex items-end gap-1 border border-cyan-300/20 bg-black/25 px-2 pb-2 pt-3">{bars.map((height, index) => <span key={index} className="flex-1 bg-gradient-to-t from-emerald-500/25 to-cyan-300" style={{ height: `${height}%` }} />)}</div></div><div className="grid grid-rows-2 gap-2"><div className="relative grid place-items-center border border-cyan-300/20 bg-black/25"><span className="size-12 rounded-full" style={{ background: "conic-gradient(#22d3ee 0 68%, rgba(34,211,238,.12) 68%)" }} /><span className="absolute size-8 rounded-full bg-[#031017]" /><i className="absolute text-[8px] font-semibold not-italic text-cyan-100">68%</i></div><div className="space-y-1.5 border border-emerald-300/20 bg-black/25 p-2">{[82, 64, 91].map((width, index) => <span key={index} className="block h-1 bg-white/10"><i className="block h-full bg-emerald-300/70" style={{ width: `${width}%` }} /></span>)}</div></div></div><span className="absolute left-1 top-1 size-3 border-l border-t border-cyan-300/80" /><span className="absolute bottom-1 right-1 size-3 border-b border-r border-emerald-300/80" /></div>;

  return <div className={cn("dashboard-preview relative h-36 overflow-hidden rounded-xl border p-3", ana ? "border-pink-300/20 bg-[#160c19]" : "border-white/[0.07] bg-[#090d1d]")}><div className="mb-2.5 grid grid-cols-3 gap-2">{[0, 1, 2].map((item) => <span key={item} className="h-7 rounded-md border border-white/[0.06] bg-white/[0.035] p-2"><i className={cn("block h-1 rounded-full opacity-70", accent, item === 0 ? "w-7" : "w-5")} /></span>)}</div><div className="grid h-[74px] grid-cols-[1.8fr_1fr] gap-2"><div className="flex items-end gap-1.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-2 pb-2 pt-3">{bars.map((height, index) => <span key={index} className={cn("flex-1 rounded-sm bg-gradient-to-t", ana ? "from-pink-600/45 to-pink-300" : "from-violet-600/35 to-sky-300/80")} style={{ height: `${height}%` }} />)}</div><div className="relative grid place-items-center rounded-lg border border-white/[0.06] bg-white/[0.02]"><span className={cn("size-11 rounded-full", ana ? "bg-pink-400/25" : "bg-sky-400/25")} /><span className="absolute size-7 rounded-full bg-[#0b0f18]" /><i className={cn("absolute size-1.5 rounded-full", accent)} /></div></div></div>;
}

export function DashboardHub({ dashboards, query, open, create, showTemplates, remove, clearSearch, theme }: { dashboards: DashboardSummary[]; query: string; open: (id: string) => void; create: () => void; showTemplates: () => void; remove: (dashboard: DashboardSummary) => void; clearSearch: () => void; theme: DashboardTheme }) {
  return <div className="mx-auto w-full max-w-[1440px] px-4 py-7 sm:px-7 lg:px-9 lg:py-9">
    <section className="flex flex-col gap-5 border-b border-white/[.07] pb-7 sm:flex-row sm:items-end sm:justify-between">
      <div><p className="text-sm font-medium text-sky-300">{dashboards.length} dashboard{dashboards.length === 1 ? "" : "s"}</p><h1 className="mt-1 text-3xl font-semibold tracking-[-0.04em] text-white sm:text-4xl">Dashboards</h1><p className="mt-2 max-w-xl text-sm leading-relaxed text-slate-400 sm:text-base">Abra uma visão existente ou crie uma nova com seus dados.</p></div>
      <div className="flex flex-col gap-2 sm:flex-row"><Button onClick={showTemplates} variant="outline" className="min-h-11 rounded-lg border-white/[.1] bg-transparent text-slate-200 hover:border-sky-300/25 hover:bg-sky-300/[.04]"><LayoutTemplate />Ver templates</Button><Button onClick={create} className="min-h-11 rounded-lg bg-sky-500 px-5 text-slate-950 shadow-sm hover:bg-sky-400"><Plus />Criar dashboard</Button></div>
    </section>
    <section className="mt-7"><div className="mb-5 flex items-center justify-between gap-4"><div><h2 className="text-lg font-semibold tracking-tight text-white">Suas visualizações</h2><p className="mt-1 text-sm text-slate-500">A AnaCraft é um exemplo completo e pode ser duplicada.</p></div></div>
      <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{dashboards.map((dashboard) => <article key={dashboard.id} className={cn("dashboard-card group relative rounded-[18px] border bg-[#11151d] p-4 transition duration-300", dashboard.kind === "anacraft" ? "border-pink-400/18 hover:border-pink-400/30" : "border-white/[0.08] hover:border-sky-400/25")}>{dashboard.kind !== "anacraft" && <button onClick={() => remove(dashboard)} className="absolute right-5 top-5 z-10 grid size-11 place-items-center rounded-lg border border-white/[0.08] bg-[#0b0f14]/95 text-slate-400 transition hover:border-rose-400/30 hover:bg-rose-400/10 hover:text-rose-300" aria-label={`Excluir ${dashboard.name}`} title="Excluir dashboard"><Trash2 className="size-4" /></button>}<button className="block w-full rounded-lg text-left" onClick={() => open(dashboard.id)} aria-label={`Abrir dashboard ${dashboard.name}`}><DashboardMiniPreview kind={dashboard.kind} model={dashboard.model} theme={theme} /><div className="px-1 pb-1 pt-4"><div className="flex items-start justify-between gap-3"><div><span className={cn("mb-2 inline-flex rounded-md border px-2 py-0.5 text-xs font-semibold uppercase tracking-[0.1em]", dashboard.kind === "anacraft" ? "border-pink-300/20 bg-pink-300/[0.06] text-pink-200" : "border-sky-300/15 bg-sky-300/[0.05] text-sky-200")}>{dashboard.kind === "anacraft" ? "Caso demonstrativo" : `Design ${modelName(dashboard.model)}`}</span><h3 className="font-semibold text-white transition group-hover:text-sky-100">{dashboard.name}</h3><p className="mt-1 line-clamp-2 text-sm leading-relaxed text-slate-400">{dashboard.description}</p></div><span className="grid size-9 shrink-0 place-items-center rounded-lg border border-white/[0.07] bg-white/[0.025] text-slate-400 transition group-hover:text-sky-300"><ChevronRight className="size-4" /></span></div><div className="mt-4 flex items-center justify-between border-t border-white/[0.06] pt-3 text-xs text-slate-500"><span>{dashboard.kind === "anacraft" ? "Dados simulados" : `${dashboard.widgetCount} widgets`}</span><span>{dashboard.kind === "anacraft" ? "Pronto para explorar" : dashboard.updatedAt}</span></div></div></button></article>)}
        {!dashboards.length && <div className="grid min-h-[200px] place-items-center rounded-[22px] border border-white/[0.08] bg-white/[0.02] p-6 text-center md:col-span-2 xl:col-span-3"><div><Search className="mx-auto size-7 text-slate-500" /><p className="mt-3 font-medium text-white">Nenhum resultado para “{query}”</p><p className="mt-1 text-sm text-slate-400">Confira o termo ou volte a visualizar todos os dashboards.</p><Button onClick={clearSearch} variant="outline" className="mt-4 min-h-11 border-white/[.09] bg-white/[.025] text-slate-200"><RotateCcw />Limpar busca</Button></div></div>}
        <button onClick={create} className="group grid min-h-[220px] place-items-center rounded-[22px] border border-dashed border-white/[0.12] bg-white/[0.015] p-6 text-center transition hover:border-cyan-300/30 hover:bg-cyan-300/[0.025] md:min-h-[282px]"><span><span className="mx-auto grid size-12 place-items-center rounded-2xl border border-white/[0.08] bg-white/[0.035] text-slate-400 transition group-hover:text-cyan-300"><Plus /></span><span className="mt-4 block text-sm font-semibold text-slate-300">Novo dashboard</span><span className="mt-1 block text-sm text-slate-500">Comece com um template ou do zero</span></span></button>
      </div>
    </section>
  </div>;
}

function Metric({ item }: { item: (typeof metrics)[number] }) {
  const tone = item.tone === "cyan" ? "bg-cyan-400/[.08] text-cyan-300" : item.tone === "blue" ? "bg-blue-500/[.08] text-blue-300" : "bg-violet-500/[.08] text-violet-300";
  return <article className="rounded-2xl border border-white/[0.08] bg-[#11151d] p-5 shadow-[0_8px_24px_rgba(3,5,14,.14)]"><div className="flex items-center justify-between"><span className={cn("grid size-10 place-items-center rounded-lg", tone)}><item.icon className="size-[18px]" /></span><span className="flex items-center gap-1 text-xs font-semibold text-emerald-400"><TrendingUp className="size-3" />{item.change}</span></div><p className="mt-5 text-2xl font-semibold tracking-[-0.035em] text-white">{item.value}</p><p className="mt-1 text-sm text-slate-400">{item.label}</p></article>;
}

type WidgetId = "revenue" | "orders" | "production" | "shipped" | "ticket" | "clients" | "sales" | "categories" | "recent" | "goal" | "insight" | "topProduct" | "inventory" | "deadlines";
type WidgetSize = "small" | "medium" | "large" | "full";
type WidgetSetting = { id: WidgetId; label: string; size: WidgetSize; visible: boolean };

const defaultWidgets: WidgetSetting[] = [
  { id: "revenue", label: "Faturamento", size: "small", visible: true },
  { id: "orders", label: "Pedidos", size: "small", visible: true },
  { id: "production", label: "Em produção", size: "small", visible: true },
  { id: "shipped", label: "Pedidos enviados", size: "small", visible: true },
  { id: "ticket", label: "Ticket médio", size: "small", visible: true },
  { id: "clients", label: "Novos clientes", size: "small", visible: true },
  { id: "sales", label: "Evolução do faturamento", size: "large", visible: true },
  { id: "categories", label: "Vendas por categoria", size: "medium", visible: true },
  { id: "recent", label: "Pedidos recentes", size: "large", visible: true },
  { id: "goal", label: "Meta mensal", size: "medium", visible: true },
  { id: "insight", label: "Insight do período", size: "medium", visible: true },
  { id: "topProduct", label: "Produto mais vendido", size: "medium", visible: true },
  { id: "inventory", label: "Alertas de estoque", size: "medium", visible: true },
  { id: "deadlines", label: "Prazos de produção", size: "medium", visible: true },
];

const minimalWidgetIds: WidgetId[] = ["revenue", "orders", "ticket", "sales", "goal", "recent"];

function widgetsForModel(model: DashboardModel): WidgetSetting[] {
  const visibleByModel: Record<DashboardModel, WidgetId[]> = {
    simple: minimalWidgetIds,
    turbo: ["revenue", "orders", "production", "shipped", "ticket", "clients", "sales", "categories", "goal"],
    pro: defaultWidgets.map((item) => item.id),
    premium: defaultWidgets.map((item) => item.id),
  };
  return defaultWidgets.map((item) => ({
    ...item,
    visible: visibleByModel[model].includes(item.id),
    size: model === "simple" && item.id === "sales" ? "full" : item.size,
  }));
}

const sizeClasses: Record<WidgetSize, string> = {
  small: "md:col-span-6 xl:col-span-3",
  medium: "md:col-span-6 xl:col-span-4",
  large: "md:col-span-12 xl:col-span-8",
  full: "md:col-span-12",
};

function WidgetContent({ id, showcase = false }: { id: WidgetId; showcase?: boolean }) {
  const metricIds: WidgetId[] = ["revenue", "orders", "production", "shipped", "ticket", "clients"];
  const revenueColor = showcase ? "#ff6987" : "#8b5cf6";
  const revenueDot = showcase ? "#ffc0cf" : "#22d3ee";
  const revenueFillId = showcase ? "anacraftRevenueFill" : "customRevenueFill";
  const categories = showcase ? categoryData.map((item, index) => ({ ...item, color: ["#ff6987", "#ff9ab0", "#f472b6", "#be185d"][index] })) : categoryData;
  if (metricIds.includes(id)) {
    const index = metricIds.indexOf(id);
    return <Metric item={metrics[index]} />;
  }
  if (id === "sales") return <article className="h-full rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90 p-5 sm:p-6"><div className="mb-6 flex items-start justify-between gap-4"><div><h2 className="font-semibold text-white">Evolução do faturamento</h2><p className="mt-1 text-sm text-slate-500">Comparativo dos últimos seis meses</p></div><span className="rounded-lg border border-white/[0.07] bg-white/[0.03] px-3 py-1.5 text-xs text-slate-400">6 meses</span></div><div className="h-[270px] w-full"><ResponsiveContainer width="100%" height="100%" minWidth={1} minHeight={1}><AreaChart data={salesData} margin={{ top: 5, right: 5, left: -22, bottom: 0 }}><defs><linearGradient id={revenueFillId} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={revenueColor} stopOpacity={0.38} /><stop offset="100%" stopColor={revenueColor} stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="rgba(255,255,255,.055)" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#64748b", fontSize: 12 }} dy={10} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#64748b", fontSize: 11 }} tickFormatter={(value) => `${value / 1000}k`} /><ChartTooltip contentStyle={{ background: "#11172b", border: "1px solid rgba(255,255,255,.1)", borderRadius: 12, color: "white" }} formatter={(value) => [`R$ ${Number(value).toLocaleString("pt-BR")}`, "Faturamento"]} /><Area type="monotone" dataKey="revenue" stroke={revenueColor} strokeWidth={3} fill={`url(#${revenueFillId})`} activeDot={{ r: 5, fill: revenueDot, stroke: "#11172b", strokeWidth: 3 }} /></AreaChart></ResponsiveContainer></div></article>;
  if (id === "categories") return <article className="h-full rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90 p-5 sm:p-6"><h2 className="font-semibold text-white">Vendas por categoria</h2><p className="mt-1 text-sm text-slate-500">Participação no faturamento</p><div className="relative mx-auto h-[190px] max-w-[250px]"><ResponsiveContainer width="100%" height="100%" minWidth={1} minHeight={1}><PieChart><Pie data={categories} dataKey="value" innerRadius={58} outerRadius={78} paddingAngle={4} stroke="none">{categories.map((item) => <Cell key={item.name} fill={item.color} />)}</Pie></PieChart></ResponsiveContainer><div className="pointer-events-none absolute inset-0 grid place-items-center text-center"><div><p className="text-2xl font-semibold text-white">143</p><p className="text-xs text-slate-500">pedidos</p></div></div></div><div className="grid grid-cols-2 gap-3">{categories.map((item) => <div key={item.name} className="flex items-center gap-2 text-xs text-slate-400"><span className="size-2 rounded-full" style={{ backgroundColor: item.color }} /><span className="flex-1">{item.name}</span><strong className="font-medium text-slate-200">{item.value}%</strong></div>)}</div></article>;
  if (id === "recent") return <article className="h-full overflow-hidden rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90"><div className="flex items-center justify-between px-5 py-5 sm:px-6"><div><h2 className="font-semibold text-white">Pedidos recentes</h2><p className="mt-1 text-sm text-slate-500">Amostra com {recentOrders.length} pedidos simulados</p></div><span className="rounded-md border border-white/[.07] bg-white/[.025] px-2.5 py-1 text-xs text-slate-400">Exemplo</span></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-y border-white/[0.06] bg-white/[0.018] text-xs text-slate-500"><tr><th className="px-6 py-3 font-medium">Pedido</th><th className="px-4 py-3 font-medium">Cliente</th><th className="px-4 py-3 font-medium">Item</th><th className="px-4 py-3 font-medium">Valor</th><th className="px-4 py-3 font-medium">Status</th></tr></thead><tbody>{recentOrders.map((order) => <tr key={order.id} className="border-b border-white/[0.05] last:border-0"><td className="px-6 py-4 font-medium text-cyan-300">{order.id}</td><td className="px-4 py-4 text-slate-300">{order.client}</td><td className="px-4 py-4 text-slate-500">{order.item}</td><td className="px-4 py-4 font-medium text-slate-200">{order.value}</td><td className="px-4 py-4"><span className={cn("rounded-full px-2.5 py-1 text-xs font-medium", order.status === "Concluído" ? "bg-emerald-400/10 text-emerald-300" : order.status === "Pendente" ? "bg-amber-400/10 text-amber-300" : order.status === "Enviado" ? "bg-blue-400/10 text-blue-300" : "bg-violet-400/10 text-violet-300")}>{order.status}</span></td></tr>)}</tbody></table></div></article>;
  if (id === "goal") return <article className="h-full rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90 p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-cyan-400/10 text-cyan-300"><Target className="size-[18px]" /></span><div><h2 className="font-semibold text-white">Meta mensal</h2><p className="text-xs text-slate-500">R$ 18.460 de R$ 24.000</p></div></div><div className="mt-6 flex items-end justify-between"><span className="text-3xl font-semibold tracking-tight text-white">76,9%</span><span className="text-xs text-slate-500">faltam R$ 5.540</span></div><Progress value={76.9} className="mt-4 h-2 bg-white/[0.06] [&>div]:bg-gradient-to-r [&>div]:from-violet-500 [&>div]:to-cyan-400" /></article>;
  if (id === "topProduct") return <article className="relative h-full overflow-hidden rounded-[22px] border border-violet-400/15 bg-[#0d1122]/90 p-5 sm:p-6"><div className="absolute -right-12 -top-12 size-36 rounded-full bg-violet-500/15 blur-3xl" /><div className="relative"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-violet-300">Produto campeão</p><h2 className="mt-2 text-lg font-semibold text-white">Caneca personalizada</h2></div><span className="grid size-11 place-items-center rounded-xl bg-violet-500/15 text-violet-300"><Sparkles className="size-5" /></span></div><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl border border-white/[0.06] bg-white/[0.025] p-3"><p className="text-2xl font-semibold text-white">42</p><p className="mt-1 text-xs text-slate-500">unidades vendidas</p></div><div className="rounded-xl border border-white/[0.06] bg-white/[0.025] p-3"><p className="text-2xl font-semibold text-cyan-300">R$ 4.830</p><p className="mt-1 text-xs text-slate-500">em faturamento</p></div></div><p className="mt-4 text-xs leading-relaxed text-slate-400">Representa 26% das vendas do mês e cresceu 21% sobre setembro.</p></div></article>;
  if (id === "inventory") return <article className="h-full rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90 p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-semibold text-white">Alertas de estoque</h2><p className="mt-1 text-sm text-slate-500">Itens que precisam de reposição</p></div><span className="rounded-lg bg-amber-400/10 px-2.5 py-1 text-xs font-semibold text-amber-300">3 alertas</span></div><div className="mt-5 space-y-3">{[{ name: "Caneca branca 325 ml", left: 8, tone: "bg-amber-400" }, { name: "Argola para chaveiro", left: 14, tone: "bg-cyan-400" }, { name: "Ímã adesivo", left: 6, tone: "bg-rose-400" }].map((item) => <div key={item.name} className="flex items-center gap-3 rounded-xl border border-white/[0.055] bg-white/[0.02] p-3"><span className={cn("size-2 rounded-full", item.tone)} /><span className="min-w-0 flex-1 truncate text-sm text-slate-300">{item.name}</span><strong className="text-xs font-medium text-slate-400">{item.left} un.</strong></div>)}</div></article>;
  if (id === "deadlines") return <article className="h-full rounded-[22px] border border-white/[0.075] bg-[#0d1122]/90 p-5 sm:p-6"><h2 className="font-semibold text-white">Prazos de produção</h2><p className="mt-1 text-sm text-slate-500">Situação dos pedidos ativos</p><div className="mt-6 space-y-5">{[{ label: "Dentro do prazo", value: 16, width: 67, color: "from-emerald-500 to-cyan-400" }, { label: "Entrega próxima", value: 6, width: 25, color: "from-amber-500 to-orange-400" }, { label: "Atrasados", value: 2, width: 8, color: "from-rose-500 to-pink-400" }].map((item) => <div key={item.label}><div className="mb-2 flex justify-between text-xs"><span className="text-slate-400">{item.label}</span><strong className="text-slate-200">{item.value} pedidos</strong></div><div className="h-2 overflow-hidden rounded-full bg-white/[0.05]"><div className={cn("h-full rounded-full bg-gradient-to-r", item.color)} style={{ width: `${item.width}%` }} /></div></div>)}</div></article>;
  return <article className="relative h-full overflow-hidden rounded-[22px] border border-violet-400/15 bg-gradient-to-br from-violet-500/[0.14] to-cyan-400/[0.05] p-5 sm:p-6"><Sparkles className="absolute right-5 top-5 size-5 text-cyan-300/50" /><p className="text-xs font-semibold uppercase tracking-[0.14em] text-violet-300">Insight do período</p><p className="mt-3 text-sm leading-relaxed text-slate-300">Canecas personalizadas cresceram <strong className="font-semibold text-white">21% neste mês</strong> e já representam sua categoria com maior receita.</p></article>;
}

function SimpleMetric({ id }: { id: "revenue" | "orders" | "ticket" | "clients" }) {
  const item = metrics[["revenue", "orders", "production", "shipped", "ticket", "clients"].indexOf(id)];
  return <article className="simple-card h-full p-5"><div className="flex items-start justify-between"><span className="grid size-10 place-items-center rounded-xl bg-violet-100 text-violet-700"><item.icon className="size-[18px]" /></span><span className="rounded-full bg-cyan-50 px-2 py-1 text-xs font-semibold text-emerald-700">{item.change}</span></div><p className="mt-5 text-2xl font-semibold tracking-[-0.04em] text-[#17213a]">{item.value}</p><p className="mt-1 text-sm text-slate-500">{item.label}</p></article>;
}

function SimpleWidget({ id }: { id: WidgetId }) {
  if (["revenue", "orders", "ticket", "clients"].includes(id)) return <SimpleMetric id={id as "revenue" | "orders" | "ticket" | "clients"} />;
  if (id === "sales") return <article className="simple-card h-full p-5 sm:p-6"><div className="mb-6 flex items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.13em] text-violet-600">Fluxo mensal</p><h2 className="mt-1 text-lg font-semibold text-[#17213a]">Entradas e desempenho</h2></div><span className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-xs text-slate-500">6 meses</span></div><div className="h-[250px]"><ResponsiveContainer width="100%" height="100%" minWidth={1} minHeight={1}><BarChart data={salesData} barGap={3} margin={{ top: 5, right: 5, left: -24, bottom: 0 }}><CartesianGrid vertical={false} stroke="#e9edf5" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#94a3b8", fontSize: 11 }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#94a3b8", fontSize: 10 }} tickFormatter={(value) => `${value / 1000}k`} /><ChartTooltip contentStyle={{ background: "#fff", border: "1px solid #e2e8f0", borderRadius: 12, color: "#17213a", boxShadow: "0 12px 30px rgba(15,23,42,.08)" }} formatter={(value) => [`R$ ${Number(value).toLocaleString("pt-BR")}`, "Faturamento"]} /><Bar dataKey="previous" fill="#dbeafe" radius={[5, 5, 0, 0]} /><Bar dataKey="revenue" fill="#7c3aed" radius={[5, 5, 0, 0]} /></BarChart></ResponsiveContainer></div></article>;
  if (id === "goal") return <article className="simple-card h-full p-5 sm:p-6"><div className="flex items-center justify-between"><span className="grid size-11 place-items-center rounded-xl bg-cyan-100 text-cyan-700"><Target className="size-5" /></span><button onClick={() => toast.info("Abra Personalizar para ajustar os widgets e metas do painel.")} className="text-xs font-medium text-violet-600">Ajustar meta</button></div><p className="mt-6 text-sm text-slate-500">Meta de faturamento</p><p className="mt-1 text-3xl font-semibold tracking-[-0.04em] text-[#17213a]">76,9%</p><div className="mt-5 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-[77%] rounded-full bg-gradient-to-r from-violet-600 to-cyan-400" /></div><div className="mt-3 flex justify-between text-xs text-slate-400"><span>R$ 18.460</span><span>R$ 24.000</span></div><div className="mt-7 rounded-xl bg-[#f6f3ff] p-4"><p className="text-xs font-semibold text-violet-700">Bom ritmo</p><p className="mt-1 text-xs leading-relaxed text-slate-500">Mantendo a média atual, a meta será atingida antes do fim do mês.</p></div></article>;
  if (id === "recent") return <article className="simple-card overflow-hidden"><div className="flex items-center justify-between px-5 py-5 sm:px-6"><div><h2 className="font-semibold text-[#17213a]">Pedidos recentes</h2><p className="mt-1 text-sm text-slate-500">Últimas movimentações do negócio</p></div><button onClick={() => toast.info("Todos os pedidos da demonstração já estão visíveis.")} className="text-xs font-semibold text-violet-600">Ver todos</button></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-y border-slate-100 bg-slate-50/80 text-xs text-slate-400"><tr><th className="px-6 py-3 font-medium">Pedido</th><th className="px-4 py-3 font-medium">Cliente</th><th className="px-4 py-3 font-medium">Produto</th><th className="px-4 py-3 font-medium">Valor</th><th className="px-4 py-3 font-medium">Status</th></tr></thead><tbody>{recentOrders.map((order) => <tr key={order.id} className="border-b border-slate-100 last:border-0"><td className="px-6 py-4 font-semibold text-violet-700">{order.id}</td><td className="px-4 py-4 text-slate-700">{order.client}</td><td className="px-4 py-4 text-slate-500">{order.item}</td><td className="px-4 py-4 font-medium text-slate-700">{order.value}</td><td className="px-4 py-4"><span className={cn("rounded-full px-2.5 py-1 text-xs font-medium", order.status === "Concluído" ? "bg-emerald-50 text-emerald-700" : order.status === "Pendente" ? "bg-amber-50 text-amber-700" : order.status === "Enviado" ? "bg-blue-50 text-blue-700" : "bg-violet-50 text-violet-700")}>{order.status}</span></td></tr>)}</tbody></table></div></article>;
  if (id === "categories") return <article className="simple-card h-full p-5"><h2 className="font-semibold text-[#17213a]">Categorias</h2><p className="mt-1 text-sm text-slate-500">Participação nas vendas</p><div className="mt-6 space-y-4">{categoryData.slice(0, 3).map((item) => <div key={item.name}><div className="mb-1.5 flex justify-between text-xs"><span className="text-slate-600">{item.name}</span><strong className="text-slate-700">{item.value}%</strong></div><div className="h-1.5 rounded-full bg-slate-100"><div className="h-full rounded-full" style={{ width: `${item.value}%`, backgroundColor: item.color }} /></div></div>)}</div></article>;
  return <article className="simple-card h-full bg-gradient-to-br from-violet-50 to-cyan-50 p-5"><Sparkles className="size-5 text-violet-500" /><p className="mt-4 text-xs font-semibold uppercase tracking-[0.13em] text-violet-600">Insight do período</p><p className="mt-2 text-sm leading-relaxed text-slate-600">Canecas personalizadas cresceram <strong className="text-[#17213a]">21% neste mês</strong>.</p></article>;
}

export function MinimalDashboard({ back, name }: { back: () => void; name: string }) {
  const defaults = useMemo(() => widgetsForModel("simple").filter((item) => minimalWidgetIds.includes(item.id)), []);
  const storageKey = useMemo(() => `dashhub:simple:${name}`, [name]);
  const [widgets, setWidgets] = useState<WidgetSetting[]>(defaults);
  const [draft, setDraft] = useState<WidgetSetting[]>(defaults);
  const [panelOpen, setPanelOpen] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [simpleQuery, setSimpleQuery] = useState("");
  useEffect(() => { const timer = window.setTimeout(() => { const parsed = loadWidgetLayout<WidgetSetting>(storageKey, defaults).filter((item) => minimalWidgetIds.includes(item.id)); setWidgets(parsed); setDraft(parsed); }, 0); return () => window.clearTimeout(timer); }, [defaults, storageKey]);
  const shown = widgets.filter((item) => item.visible && item.label.toLowerCase().includes(simpleQuery.trim().toLowerCase()));
  const update = (id: WidgetId, visible: boolean) => setDraft((items) => items.map((item) => item.id === id ? { ...item, visible } : item));
  const move = (id: WidgetId, direction: -1 | 1) => setDraft((items) => { const index = items.findIndex((item) => item.id === id); const target = index + direction; if (index < 0 || target < 0 || target >= items.length) return items; const copy = [...items]; [copy[index], copy[target]] = [copy[target], copy[index]]; return copy; });
  const openEditor = () => { setDraft(widgets.map((item) => ({ ...item }))); setPanelOpen(true); };
  const save = () => { setWidgets(draft); saveWidgetLayout(storageKey, draft); setPanelOpen(false); };
  const span = (id: WidgetId) => ["revenue", "orders", "ticket", "clients"].includes(id) ? "lg:col-span-3" : id === "sales" ? "lg:col-span-8" : id === "recent" ? "lg:col-span-12" : "lg:col-span-4";
  const simpleNav = [{ label: "Visão geral", icon: LayoutDashboard }, { label: "Pedidos", icon: ShoppingBag }, { label: "Financeiro", icon: CircleDollarSign }, { label: "Metas", icon: Target }, { label: "Configurações", icon: Settings }];
  return <div className="min-h-screen bg-[#f6f8fc] text-[#17213a]">
    <button type="button" aria-label="Fechar menu" className={cn("fixed inset-0 z-40 bg-slate-900/25 backdrop-blur-sm lg:hidden", mobileMenu ? "block" : "hidden")} onClick={() => setMobileMenu(false)} />
    <aside aria-label="Navegação do dashboard Minimal" className={cn("fixed inset-y-0 left-0 z-50 flex w-[min(236px,calc(100vw-48px))] flex-col border-r border-[#e4e8f1] bg-[#f2f5fb] p-5 transition-transform lg:w-[236px] lg:translate-x-0", mobileMenu ? "translate-x-0" : "-translate-x-full")}><div className="flex items-center justify-between"><button onClick={back} className="flex min-h-11 items-center gap-3" aria-label="Voltar ao hub"><span className="grid size-10 place-items-center rounded-[14px] bg-gradient-to-br from-violet-600 to-cyan-400 text-white shadow-[0_10px_25px_rgba(124,58,237,.18)]"><BarChart3 className="size-5" /></span><span className="text-lg font-semibold tracking-tight">FlowView</span></button><button onClick={() => setMobileMenu(false)} className="grid size-11 place-items-center rounded-xl lg:hidden" aria-label="Fechar menu"><X className="size-5 text-slate-500" /></button></div><nav className="mt-9 space-y-1.5" aria-label="Seções do dashboard">{simpleNav.map((item, index) => <button key={item.label} onClick={() => index !== 0 && toast.info("Esta seção está resumida na visão geral da demonstração.")} aria-current={index === 0 ? "page" : undefined} className={cn("flex min-h-11 w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-medium transition", index === 0 ? "bg-white text-violet-700 shadow-[0_8px_24px_rgba(15,23,42,.06)]" : "text-slate-500 hover:bg-white/70 hover:text-slate-800")}><item.icon className="size-[18px]" />{item.label}</button>)}</nav><div className="mt-auto rounded-2xl bg-gradient-to-br from-violet-600 to-blue-600 p-4 text-white shadow-[0_16px_36px_rgba(91,33,182,.18)]"><Palette className="size-5 text-cyan-200" /><p className="mt-4 text-sm font-semibold">Seu painel, seu jeito</p><p className="mt-1 text-xs leading-relaxed text-violet-100/80">Escolha os indicadores que fazem sentido para você.</p><button onClick={openEditor} className="mt-4 min-h-11 w-full rounded-xl bg-white px-3 py-2 text-sm font-semibold text-violet-700">Personalizar</button></div></aside>
    <div className="lg:pl-[236px]"><header className="sticky top-0 z-30 flex min-h-[74px] items-center gap-3 border-b border-[#e7eaf2] bg-white/90 px-4 py-3 backdrop-blur-xl sm:gap-4 sm:px-7"><button onClick={() => setMobileMenu(true)} className="grid size-11 shrink-0 place-items-center rounded-xl border border-slate-200 text-slate-600 lg:hidden" aria-label="Abrir menu"><Menu className="size-5" /></button><div className="min-w-0"><p className="truncate text-lg font-semibold tracking-tight">{name}</p><p className="hidden text-xs text-slate-400 sm:block">Design Minimal · visão objetiva</p></div><div className="ml-auto flex items-center gap-2"><div className="relative hidden md:block"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" /><input value={simpleQuery} onChange={(event) => setSimpleQuery(event.target.value)} className="h-10 w-56 rounded-xl border border-slate-200 bg-slate-50 pl-9 pr-3 text-sm outline-none transition focus:border-violet-300 focus:bg-white" placeholder="Buscar indicador" aria-label="Buscar indicador" /></div><button onClick={() => toast.info("Nenhuma notificação nova.")} className="relative grid size-11 place-items-center rounded-xl border border-slate-200 bg-white text-slate-500" aria-label="Notificações"><Bell className="size-4" /><span className="absolute right-2.5 top-2 size-1.5 rounded-full bg-cyan-400" /></button><button onClick={back} className="hidden min-h-11 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-semibold text-slate-600 sm:block">Voltar ao Hub</button></div></header>
      <main className="mx-auto max-w-[1420px] px-4 py-6 sm:px-7 lg:py-8"><div className="relative mb-5 md:hidden"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" /><input value={simpleQuery} onChange={(event) => setSimpleQuery(event.target.value)} className="h-11 w-full rounded-xl border border-slate-200 bg-white pl-10 pr-3 text-slate-900 outline-none transition focus:border-violet-400" placeholder="Buscar indicador" aria-label="Buscar indicador" /></div><div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-violet-600">Visão geral</p><h1 className="mt-1 text-2xl font-semibold tracking-[-0.04em] sm:text-3xl">Informações importantes, sem excesso.</h1><p className="mt-2 text-sm text-slate-500">Acompanhe o desempenho principal e ajuste o painel quando precisar.</p></div><Button onClick={openEditor} className="h-11 w-full rounded-xl bg-[#17213a] px-4 text-white hover:bg-violet-700 sm:w-auto"><Palette />Editar apresentação</Button></div>
        <section className="mb-4 grid gap-4 md:grid-cols-2 lg:grid-cols-4"><article className="relative overflow-hidden rounded-[22px] bg-gradient-to-br from-[#21164b] to-violet-700 p-5 text-white shadow-[0_18px_40px_rgba(76,29,149,.18)]"><div className="absolute -right-10 -top-10 size-36 rounded-full bg-cyan-300/15 blur-2xl" /><div className="relative"><div className="flex items-center justify-between"><span className="text-xs font-medium text-violet-100">Saldo atual</span><CircleDollarSign className="size-5 text-cyan-300" /></div><p className="mt-7 text-3xl font-semibold tracking-[-0.05em]">R$ 56.200</p><p className="mt-2 text-xs text-violet-200/70">Atualizado hoje, 09:24</p></div></article>{shown.filter((item) => ["revenue", "orders", "ticket"].includes(item.id)).map((item) => <div key={item.id}><SimpleWidget id={item.id} /></div>)}</section>
        <section className="grid grid-cols-1 gap-4 lg:grid-cols-12">{shown.filter((item) => !["revenue", "orders", "ticket"].includes(item.id)).map((item) => <div key={item.id} className={cn("min-w-0", span(item.id))}><SimpleWidget id={item.id} /></div>)}</section>
      </main>
    </div>
    <Sheet open={panelOpen} onOpenChange={setPanelOpen}><SheetContent className="border-slate-200 bg-white text-[#17213a] sm:max-w-md"><SheetHeader className="border-b border-slate-100 px-5 py-5"><SheetTitle className="text-lg text-[#17213a]">Editar apresentação</SheetTitle><SheetDescription className="text-slate-500">Ative, oculte e reorganize os blocos do design Minimal.</SheetDescription></SheetHeader><div className="flex-1 space-y-3 overflow-y-auto px-4 py-3">{draft.map((item, index) => <div key={item.id} className="rounded-xl border border-slate-200 bg-slate-50/70 p-3"><div className="flex items-center gap-3"><GripVertical className="size-4 text-slate-400" /><p className="min-w-0 flex-1 truncate text-sm font-medium text-slate-700">{item.label}</p><Switch checked={item.visible} onCheckedChange={(checked) => update(item.id, checked)} aria-label={`Exibir ${item.label}`} /></div><div className="mt-2 flex justify-end gap-1 border-t border-slate-200 pt-2"><Button variant="ghost" size="icon-xs" disabled={index === 0} onClick={() => move(item.id, -1)} className="text-slate-500" aria-label={`Mover ${item.label} para cima`}><ArrowUp /></Button><Button variant="ghost" size="icon-xs" disabled={index === draft.length - 1} onClick={() => move(item.id, 1)} className="text-slate-500" aria-label={`Mover ${item.label} para baixo`}><ArrowDown /></Button></div></div>)}</div><SheetFooter className="border-t border-slate-100 bg-white p-4"><Button variant="ghost" onClick={() => setDraft(defaults)} className="justify-start text-slate-500"><RotateCcw />Restaurar design</Button><div className="grid grid-cols-2 gap-2"><Button variant="outline" onClick={() => setPanelOpen(false)} className="border-slate-200 text-slate-600">Cancelar</Button><Button onClick={save} className="bg-violet-700 text-white hover:bg-violet-600"><Check />Aplicar</Button></div></SheetFooter></SheetContent></Sheet>
  </div>;
}

export function ShowcaseDashboard({ back, name, model, duplicate, showcase = false }: { back: () => void; name: string; model: DashboardModel; duplicate: () => void; showcase?: boolean }) {
  const modelWidgets = useMemo(() => widgetsForModel(model), [model]);
  const storageKey = useMemo(() => `dashhub:widgets:${name}`, [name]);
  const [widgets, setWidgets] = useState<WidgetSetting[]>(modelWidgets);
  const [draft, setDraft] = useState<WidgetSetting[]>(modelWidgets);
  const [editing, setEditing] = useState(false);
  const [panelOpen, setPanelOpen] = useState(false);
  const [dragged, setDragged] = useState<WidgetId | null>(null);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      const legacyKey = name === "AnaCraft Ateliê" ? "dashhub:anacraft-widgets" : storageKey;
      const parsed = loadWidgetLayout<WidgetSetting>(storageKey, loadWidgetLayout<WidgetSetting>(legacyKey, modelWidgets));
      const hydrated = [...parsed, ...modelWidgets.filter((item) => !parsed.some((savedItem) => savedItem.id === item.id))];
      setWidgets(hydrated); setDraft(hydrated);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [modelWidgets, name, storageKey]);
  const shown = (editing ? draft : widgets).filter((item) => item.visible);
  const hiddenCount = (editing ? draft : widgets).filter((item) => !item.visible).length;
  const update = (id: WidgetId, patch: Partial<WidgetSetting>) => setDraft((items) => items.map((item) => item.id === id ? { ...item, ...patch } : item));
  const move = (id: WidgetId, direction: -1 | 1) => setDraft((items) => { const index = items.findIndex((item) => item.id === id); const target = index + direction; if (index < 0 || target < 0 || target >= items.length) return items; const copy = [...items]; [copy[index], copy[target]] = [copy[target], copy[index]]; return copy; });
  const dropOn = (target: WidgetId) => { if (!dragged || dragged === target) return; setDraft((items) => { const sourceIndex = items.findIndex((item) => item.id === dragged); const targetIndex = items.findIndex((item) => item.id === target); const copy = [...items]; const [source] = copy.splice(sourceIndex, 1); copy.splice(targetIndex, 0, source); return copy; }); setDragged(null); };
  const cycleSize = (item: WidgetSetting) => { const sizes: WidgetSize[] = ["small", "medium", "large", "full"]; update(item.id, { size: sizes[(sizes.indexOf(item.size) + 1) % sizes.length] }); };
  const startEditing = () => { setDraft(widgets.map((item) => ({ ...item }))); setEditing(true); setPanelOpen(true); };
  const cancel = () => { setDraft(widgets.map((item) => ({ ...item }))); setEditing(false); setPanelOpen(false); };
  const save = () => { setWidgets(draft); saveWidgetLayout(storageKey, draft); setEditing(false); setPanelOpen(false); };

  return <div className={cn("mx-auto w-full max-w-[1440px] px-4 py-7 sm:px-7 lg:px-9 lg:py-9", showcase && "anacraft-dashboard")}>
    <div className={cn("mb-7 flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between", showcase && "anacraft-dashboard-header")}><div className="flex min-w-0 items-center gap-3"><Button variant="ghost" size="icon" onClick={back} className="size-11 shrink-0 rounded-xl border border-white/[0.07] text-slate-400 hover:bg-white/[0.05] hover:text-white" aria-label="Voltar"><ChevronLeft /></Button>{showcase && <span className="anacraft-monogram grid size-11 shrink-0 place-items-center rounded-xl text-sm font-semibold text-white">AC</span>}<div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h1 className="break-words text-2xl font-semibold tracking-[-0.035em] text-white">{name}</h1><span className={cn("rounded-md border px-2 py-1 text-xs font-semibold uppercase tracking-wider", showcase ? "border-pink-300/20 bg-pink-300/[0.07] text-pink-200" : "border-emerald-400/15 bg-emerald-400/[0.07] text-emerald-300")}>{showcase ? "Dados simulados" : "Salvo localmente"}</span><span className="rounded-md border border-white/[.08] bg-white/[.025] px-2 py-1 text-xs font-semibold uppercase tracking-wider text-slate-400">{showcase ? "Caso demonstrativo" : `Design ${modelName(model)}`}</span></div><p className="mt-1 text-sm text-slate-400">{showcase ? "Cenário fictício de vendas, produção, envios e estoque · outubro de 2026" : "Dados e preferências armazenados neste navegador"}</p></div></div><div className="flex w-full flex-wrap gap-2 sm:w-auto sm:justify-end">{editing ? <><Button variant="ghost" onClick={cancel} className="min-h-11 flex-1 text-slate-400 hover:bg-white/[0.05] hover:text-white sm:flex-none">Cancelar</Button><Button variant="outline" onClick={() => setPanelOpen(true)} className="min-h-11 flex-1 rounded-xl border-white/[0.09] bg-white/[0.025] text-slate-200 sm:flex-none"><Palette />Widgets {hiddenCount > 0 && `(${hiddenCount} ocultos)`}</Button><Button onClick={save} className={cn("min-h-11 w-full rounded-xl text-white sm:w-auto", showcase ? "bg-gradient-to-r from-pink-500 to-rose-400" : "bg-gradient-to-r from-violet-500 to-blue-500")}><Check />Salvar layout</Button></> : <><Button variant="outline" onClick={duplicate} className="min-h-11 flex-1 rounded-xl border-white/[0.09] bg-white/[0.025] text-slate-300 hover:bg-white/[0.06] hover:text-white sm:flex-none"><Copy />Duplicar</Button><Button onClick={startEditing} className={cn("min-h-11 flex-1 rounded-xl text-white sm:flex-none", showcase ? "bg-gradient-to-r from-pink-500 to-rose-400 hover:from-pink-400 hover:to-rose-300" : "bg-gradient-to-r from-violet-500 to-blue-500")}><Palette />Personalizar</Button></>}</div></div>
    {showcase && <section className="anacraft-snapshot mb-5 grid gap-3 rounded-[18px] border border-pink-300/15 p-3 sm:grid-cols-3"><div><span>Meta do mês</span><strong>76,9%</strong><small>R$ 18.460 de R$ 24.000</small></div><div><span>Produção</span><strong>24 pedidos</strong><small>6 entregas próximas</small></div><div><span>Expedição</span><strong>89 enviados</strong><small>+16,8% no período</small></div></section>}
    {editing && <div className="mb-5 flex items-center gap-3 rounded-2xl border border-cyan-300/15 bg-cyan-300/[0.045] px-4 py-3 text-sm text-slate-300"><GripVertical className="size-4 text-cyan-300" /><span className="flex-1">Arraste os widgets para reorganizar ou use o painel de personalização.</span><span className="hidden text-xs text-slate-500 sm:block">Alterações ainda não salvas</span></div>}
    <div className={cn("dashboard-model grid grid-cols-1 gap-4 md:grid-cols-12", `dashboard-model-${model}`, showcase && "dashboard-model-anacraft")}>{shown.map((item) => <div key={item.id} draggable={editing} onDragStart={() => setDragged(item.id)} onDragOver={(event) => { if (editing) event.preventDefault(); }} onDrop={() => dropOn(item.id)} className={cn("dashboard-widget relative min-w-0 transition", sizeClasses[item.size], editing && "cursor-grab rounded-[24px] ring-1 ring-violet-400/25 hover:ring-cyan-300/50 active:cursor-grabbing", dragged === item.id && "opacity-40")}>
      {editing && <div className="absolute -right-2 -top-2 z-20 flex items-center gap-1 rounded-lg border border-white/10 bg-[#171d35] p-1 shadow-xl"><GripVertical className="size-3.5 text-slate-500" /><button onClick={() => cycleSize(item)} className="rounded px-1.5 py-0.5 text-xs font-medium uppercase text-cyan-300 hover:bg-white/5" aria-label={`Alterar tamanho de ${item.label}`}>{item.size}</button></div>}<WidgetContent id={item.id} showcase={showcase} />
    </div>)}</div>
    <Sheet open={panelOpen} onOpenChange={setPanelOpen}><SheetContent className="border-white/[0.09] bg-[#0b0f20] text-white sm:max-w-md"><SheetHeader className="border-b border-white/[0.07] px-5 py-5"><SheetTitle className="text-lg text-white">Personalizar dashboard</SheetTitle><SheetDescription className="text-slate-500">Escolha o que aparece e organize a ordem dos widgets.</SheetDescription></SheetHeader><div className="flex-1 space-y-3 overflow-y-auto px-4 py-2">{draft.map((item, index) => <div key={item.id} className="rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><div className="flex items-center gap-3"><GripVertical className="size-4 text-slate-600" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-slate-200">{item.label}</p><button onClick={() => cycleSize(item)} className="mt-0.5 text-xs capitalize text-cyan-300 hover:text-cyan-200">Tamanho: {item.size}</button></div><Switch checked={item.visible} onCheckedChange={(checked) => update(item.id, { visible: checked })} aria-label={`Exibir ${item.label}`} /></div><div className="mt-3 flex justify-end gap-1 border-t border-white/[0.05] pt-2"><Button variant="ghost" size="icon-xs" disabled={index === 0} onClick={() => move(item.id, -1)} className="text-slate-500 hover:text-white" aria-label={`Mover ${item.label} para cima`}><ArrowUp /></Button><Button variant="ghost" size="icon-xs" disabled={index === draft.length - 1} onClick={() => move(item.id, 1)} className="text-slate-500 hover:text-white" aria-label={`Mover ${item.label} para baixo`}><ArrowDown /></Button></div></div>)}</div><SheetFooter className="border-t border-white/[0.07] bg-[#0b0f20] p-4"><Button variant="ghost" onClick={() => setDraft(modelWidgets.map((item) => ({ ...item })))} className="justify-start text-slate-400 hover:bg-white/[0.05] hover:text-white"><RotateCcw />Restaurar modelo</Button><div className="grid grid-cols-2 gap-2"><Button variant="outline" onClick={cancel} className="border-white/[0.09] bg-transparent text-slate-300">Cancelar</Button><Button onClick={save} className="bg-gradient-to-r from-violet-500 to-blue-500 text-white"><Check />Aplicar</Button></div></SheetFooter></SheetContent></Sheet>
  </div>;
}
